package com.ecommerce.controller;
import com.ecommerce.dto.AuthDtos.*; import com.ecommerce.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; private final EmailVerificationService emailVerification; public AuthController(AuthService auth,EmailVerificationService emailVerification){this.auth=auth;this.emailVerification=emailVerification;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);} @PostMapping("/verification-code") public EmailVerificationResponse sendVerification(@Valid @RequestBody EmailVerificationRequest r){String email=r.email().trim().toLowerCase();String code=emailVerification.sendCode(email);return new EmailVerificationResponse(email,"Verification code sent to "+email,code);} }
